prompt:
Create unit `tasks` and implement `clamp_all`: for lo <= hi, limit every element of `a` to [lo, hi]. The contract must state that afterwards every element is in [lo, hi] and that elements already in range are unchanged.

Required signature (in unit `tasks`):
fn clamp_all(a: &mut [i64], lo: i64, hi: i64) -> ()

reference.code:
spec fn clamped_below(a: &[i64], b: &[i64], lo: i64, hi: i64, n: usize) -> bool {
    a.len() == b.len() && (forall|k: usize| k < a.len() ==> ((k < n ==> lo <= #[trigger] a[k] && a[k] <= hi && ((lo <= b[k] && b[k] <= hi) ==> a[k] == b[k])) && (k >= n ==> a[k] == b[k])))
}

spec fn clamped_all(a: &[i64], b: &[i64], lo: i64, hi: i64) -> bool {
    a.len() == b.len() && (forall|k: usize| k < a.len() ==> lo <= #[trigger] a[k] && a[k] <= hi && ((lo <= b[k] && b[k] <= hi) ==> a[k] == b[k]))
}

#[effects(pure)]
#[uses(num::ordered, clamped_below, clamped_all)]
fn clamp_all(a: &mut [i64], lo: i64, hi: i64) -> ()
    requires num::ordered(lo, hi),
    ensures clamped_all(a, old(a), lo, hi),
{
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), lo <= hi, clamped_below(a, old(a), lo, hi, k),
        decreases a.len() - k,
    {
        if a[k] < lo {
            a[k] = lo;
        } else {
            if a[k] > hi {
                a[k] = hi;
            }
        }
        k = k + 1;
    }
}

