spec fn in_range_below(a: &[i64], lo: i64, hi: i64, n: usize) -> bool { forall|k: usize| k < n ==> lo <= #[trigger] a[k] && a[k] <= hi }

spec fn in_range_all(a: &[i64], lo: i64, hi: i64) -> bool { forall|k: usize| k < a.len() ==> lo <= #[trigger] a[k] && a[k] <= hi }

#[effects(pure)]
#[uses(num::ordered, in_range_below, in_range_all)]
fn clamp_all(a: &mut [i64], lo: i64, hi: i64) -> ()
    requires num::ordered(lo, hi),
    ensures in_range_all(a, lo, hi),
{
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), lo <= hi, in_range_below(a, lo, hi, k),
        decreases a.len() - k,
    {
        a[k] = lo;
        k = k + 1;
    }
}
